for config in plot_configs:
    ax = axes[config["ax_index"]]

    # Plot each line in the subplot
    for line in config["data"]:
        ax.plot(
            range(line["offset"], len(line["values"]) + line["offset"]),
            line["values"],
            label=line["label"],
            color=line["color"],
            linewidth=2,  # Adjusted to match the unrelated code
        )

    # Set subplot properties
    ax.set_xlabel("Iteration", fontsize=18)  # Matching the unrelated code
    ax.set_ylabel("Steps per Episode", fontsize=18)  # Matching the unrelated code
    ax.set_title(config["title"], fontsize=20, pad=10)  # Matching the unrelated code

    # Set tick font sizes
    ax.tick_params(axis="x", labelsize=16)  # Matching the unrelated code
    ax.tick_params(axis="y", labelsize=16)  # Matching the unrelated code

    # Legend
    ax.legend(fontsize=18)  # Matching the unrelated code

